-- Real dungeon maps: the game's own indoor minimap tiles, drawn by FileDataID.
-- Generated by tools/oracle_maps/build.py from the local WoW Forever client. Numbers only: no image
-- is copied; the client draws its own textures at runtime. Do not edit by hand; rebuild instead.
--
-- O.MapData.instances[key] = sheet id (wings sharing a map share its sheet)
-- O.MapData.sheets[id] = {
--   map, wmo, width, height,     game map id; the main WMO's FileDataID; the sheet's size in yards (north up)
--   origin, t, tq, offset,       world (x north, y west) -> sheet: local = R(-t) (world - origin);
--                                (ex, ey) = R(tq) local + origin; sheet = (-ey, -ex) - offset
--   base = { tile, ... },        drawn under every floor (terrain), optional
--   units = { "wmo:group", ... }, the rooms (WMO groups) the tiles belong to
--   floors = { { name, shapes, tile, ... }, ... }   lowest first; name optional; a floor may be empty
--   shapes = { x, y, w, h, band, ... }   open-air parts no tile shows (a cove, a ship's deck), drawn from the
--                                WMO's geometry and the terrain's heights: flat rectangles in yards, band 1 (low)
--                                to 6 (high); drawn under the floor's tiles
--   entrance = { x, y, floor },  where the instance portal puts you (yards, floor number)
--   entrances = { entrance, { x, y, floor }, ... },   when there are several (layout keys "entrance", "entrance2", ...)
--   start = floor,               the floor shown first when there's no entrance (a city over its sewers)
--   bosses = { [npc] = { x, y, floor } },   each boss at its spawn (the middle one of several)
-- }
-- Entrance and boss positions: creature and teleport coordinates from the cmangos classic-db
-- (GPL-3.0, github.com/cmangos/classic-db), via tools/oracle_maps/spawns.py; then any fixes made
